11	
12	const server = new Server(
13	  {
14	    name: 'reactbits-mcp-server',
15	    version: '0.1.0',
16	  },
17	  {
18	    capabilities: {
19	      tools: {},
20	    },
21	  }
22	);
23	
24	const reactBitsService = new ReactBitsService();
25	
26	// Define available tools
27	const tools: Tool[] = [
28	  {
29	    name: 'list_components',
30	    description: 'List all available ReactBits components with optional filtering',
31	    inputSchema: {
32	      type: 'object',
33	      properties: {
34	        category: {
35	          type: 'string',
36	          description: 'Filter by category (e.g., animations, backgrounds, buttons)',
37	        },
38	        style: {
39	          type: 'string',
40	          enum: ['css', 'tailwind', 'default'],
41	          description: 'Filter by styling method',
42	        },
43	        limit: {
44	          type: 'number',
45	          description: 'Maximum number of components to return',
46	        },
47	      },
48	    },
49	  },
50	  {
51	    name: 'get_component',
52	    description: 'Get the source code for a specific ReactBits component',
53	    inputSchema: {
54	      type: 'object',
55	      properties: {
56	        name: {
57	          type: 'string',
58	          description: 'Name of the component (e.g., "splash-cursor", "pixel-card")',
59	        },
60	        style: {
61	          type: 'string',
62	          enum: ['css', 'tailwind', 'default'],
63	          description: 'Preferred styling method (defaults to available)',
64	        },
65	      },
66	      required: ['name'],
67	    },
68	  },
69	  {
70	    name: 'search_components',
71	    description: 'Search for ReactBits components by name or description',
72	    inputSchema: {
73	      type: 'object',
74	      properties: {
75	        query: {
76	          type: 'string',
77	          description: 'Search query',
78	        },
79	        category: {
80	          type: 'string',
81	          description: 'Filter by category',
82	        },
83	        limit: {
84	          type: 'number',
85	          description: 'Maximum number of results',
86	        },
87	      },
88	      required: ['query'],
89	    },
90	  },
91	  {
92	    name: 'get_component_demo',
93	    description: 'Get usage example and demo code for a ReactBits component',
94	    inputSchema: {
95	      type: 'object',
96	      properties: {
97	        name: {
98	          type: 'string',
99	          description: 'Name of the component',
100	        },
101	      },
102	      required: ['name'],
103	    },
104	  },
105	  {
106	    name: 'list_categories',
107	    description: 'List all available component categories',
108	    inputSchema: {
109	      type: 'object',
110	      properties: {},
111	    },
112	  },
113	];
114	
115	// Handle list tools request
116	server.setRequestHandler(ListToolsRequestSchema, async () => {
117	  return { tools };
118	});
119	
120	// Handle tool calls
121	server.setRequestHandler(CallToolRequestSchema, async (request) => {
122	  const { name, arguments: args } = request.params;
123	
124	  try {
125	    switch (name) {
126	      case 'list_components': {
127	        const options: ComponentListOptions = {
128	          category: args?.category as string,
129	          style: args?.style as any,
130	          limit: args?.limit as number,
131	        };
132	        const components = await reactBitsService.listComponents(options);
133	        return {
134	          content: [
135	            {
136	              type: 'text',
137	              text: JSON.stringify(components, null, 2),
138	            },
139	          ],
140	        };
141	      }
142	
143	      case 'get_component': {
144	        const componentName = args?.name as string;
145	        const style = args?.style as any;
146	        
147	        if (!componentName) {
148	          throw new Error('Component name is required');
149	        }
150	
151	        const component = await reactBitsService.getComponent(componentName, style);
152	        return {
153	          content: [
154	            {
155	              type: 'text',
156	              text: component,
157	            },
158	          ],
159	        };
160	      }
161	
162	      case 'search_components': {
163	        const searchOptions: ComponentSearchOptions = {
164	          query: args?.query as string,
165	          category: args?.category as string,
166	          limit: args?.limit as number,
167	        };
168	
169	        if (!searchOptions.query) {
170	          throw new Error('Search query is required');
171	        }
172	
173	        const results = await reactBitsService.searchComponents(searchOptions);
174	        return {
175	          content: [
176	            {
177	              type: 'text',
178	              text: JSON.stringify(results, null, 2),
179	            },
180	          ],
181	        };
182	      }
183	
184	      case 'get_component_demo': {
185	        const componentName = args?.name as string;
186	        
187	        if (!componentName) {
188	          throw new Error('Component name is required');
189	        }
190	
191	        const demo = await reactBitsService.getComponentDemo(componentName);
192	        return {
193	          content: [
194	            {
195	              type: 'text',
196	              text: demo,
197	            },
198	          ],
199	        };
200	      }
201	
202	      case 'list_categories': {
203	        const categories = await reactBitsService.listCategories();
204	        return {
205	          content: [
206	            {
207	              type: 'text',
208	              text: JSON.stringify(categories, null, 2),
209	            },
210	          ],
211	        };
212	      }
213	
214	      default:
215	        throw new Error(`Unknown tool: ${name}`);
216	    }
217	  } catch (error) {
218	    const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
219	    return {
220	      content: [
221	        {
222	          type: 'text',
223	          text: `Error: ${errorMessage}`,
224	        },
225	      ],
226	      isError: true,
227	    };
228	  }
229	});
230	
231	// Start the server
232	async function main() {
233	  const transport = new StdioServerTransport();
234	  await server.connect(transport);
235	  console.error('ReactBits MCP Server started successfully');
236	}
237	
238	main().catch((error) => {
239	  console.error('Failed to start server:', error);
240	  process.exit(1);
241	});

