142	export class ReactBitsService {
143	  private cache: CacheManager;
144	  private scraper: ReactBitsScraper;
145	  private github: GitHubService;
146	
147	  constructor() {
148	    this.cache = new CacheManager();
149	    this.scraper = new ReactBitsScraper();
150	    
151	    // Use GitHub token from environment
152	    const githubToken = process.env.GITHUB_TOKEN || 
153	                       process.env.GITHUB_PERSONAL_ACCESS_TOKEN;
154	    this.github = new GitHubService(githubToken);
155	  }
156	
157	  private getComponentDependencies(slug: string): string[] {
158	    const deps: string[] = [];
159	    
160	    for (const [dep, categories] of Object.entries(componentHealth.dependencies)) {
161	      if ((categories as string[]).some((cat: string) => {
162	        const categoryData = (componentHealth.componentHealth as any)[cat];
163	        return categoryData?.components && slug in categoryData.components;
164	      })) {
165	        deps.push(dep);
166	      }
167	    }
168	    
169	    return deps;
170	  }
171	
172	  async listCategories(): Promise<string[]> {
173	    return componentRegistry.categories.map(cat => cat.name);
174	  }
175	
176	  async listComponents(options: {
177	    category?: string;
178	    style?: 'css' | 'tailwind' | 'default';
179	    limit?: number;
180	  } = {}): Promise<ReactBitsComponent[]> {
181	    let components: ReactBitsComponent[] = [];
182	
183	    // Use the auto-generated registry
184	    for (const category of componentRegistry.categories) {
185	      if (!options.category || category.slug === options.category) {
186	        const categoryHealth = (componentHealth.componentHealth as any)[category.slug] || {};
187	        
188	        components.push(...category.components.map(comp => {
189	          const componentStatus = categoryHealth.components?.[comp.slug] || 'unknown';
190	          const dependencies = this.getComponentDependencies(comp.slug);
191	          
192	          return {
193	            ...comp,
194	            description: `A ${comp.name} component from ReactBits`,
195	            quality: categoryHealth.quality,
196	            status: componentStatus,
197	            dependencies
198	          };
199	        }));
200	      }
201	    }
202	
203	    // Filter by style if specified
204	    if (options.style) {
205	      components = components.filter(comp => {
206	        if (options.style === 'css') return comp.hasCSS;
207	        if (options.style === 'tailwind') return comp.hasTailwind;
208	        return true;
209	      });
210	    }
211	
212	    // Apply limit
213	    if (options.limit && options.limit > 0) {
214	      components = components.slice(0, options.limit);
215	    }
216	
217	    return components;
218	  }
