220	  async searchComponents(options: {
221	    query: string;
222	    category?: string;
223	    limit?: number;
224	  }): Promise<ReactBitsComponent[]> {
225	    const query = options.query?.toLowerCase() || '';
226	    let components = await this.listComponents({ category: options.category });
227	
228	    // Filter by search query
229	    components = components.filter(comp =>
230	      comp.name.toLowerCase().includes(query) ||
231	      comp.slug.toLowerCase().includes(query) ||
232	      comp.description?.toLowerCase().includes(query) ||
233	      comp.category.toLowerCase().includes(query)
234	    );
235	
236	    // Apply limit
237	    if (options.limit && options.limit > 0) {
238	      components = components.slice(0, options.limit);
239	    }
240	
241	    return components;
242	  }
