326	  async getComponentDemo(componentName: string): Promise<string> {
327	    const component = await this.getComponent(componentName);
328	    
329	    // Extract component name from the code
330	    const componentNameMatch = component.match(/(?:export\s+default\s+function|const)\s+(\w+)/);
331	    const extractedName = componentNameMatch ? componentNameMatch[1] : componentName.replace(/\s+/g, '');
332	    
333	    // Create a demo wrapper
334	    return `// Demo for ${componentName}
335	import React from 'react';
336	
337	${component}
338	
339	// Usage Example:
340	export default function Demo() {
341	  return (
342	    <div className="min-h-screen bg-gray-100 p-8">
343	      <h1 className="text-2xl font-bold mb-4">${componentName} Demo</h1>
344	      <${extractedName} />
345	    </div>
346	  );
347	}`;
348	  }
349	}
