1	import axios from 'axios';
2	import * as cheerio from 'cheerio';
3	import { ComponentContent, ComponentStyle } from '../types/index.js';
4	
5	export class ReactBitsScraper {
6	  private baseUrl = 'https://reactbits.dev';
7	  
8	  async fetchComponentPage(componentSlug: string): Promise<string> {
9	    try {
10	      const url = `${this.baseUrl}/components/${componentSlug}`;
11	      const response = await axios.get(url, {
12	        headers: {
13	          'User-Agent': 'Mozilla/5.0 (compatible; ReactBitsMCP/1.0)'
14	        }
15	      });
16	      return response.data;
17	    } catch (error) {
18	      if (axios.isAxiosError(error) && error.response?.status === 404) {
19	        // Try alternative paths
20	        const altPaths = [
21	          `/text-animations/${componentSlug}`,
22	          `/animations/${componentSlug}`,
23	          `/backgrounds/${componentSlug}`,
24	          `/buttons/${componentSlug}`,
25	          `/cards/${componentSlug}`,
26	          `/navigation/${componentSlug}`,
27	          `/${componentSlug}`
28	        ];
29	        
30	        for (const path of altPaths) {
31	          try {
32	            const response = await axios.get(`${this.baseUrl}${path}`);
33	            return response.data;
34	          } catch (e) {
35	            // Continue trying other paths
36	          }
37	        }
38	      }
39	      throw new Error(`Component "${componentSlug}" not found`);
40	    }
41	  }
42	
43	  async getComponentCode(componentSlug: string, style?: ComponentStyle): Promise<ComponentContent> {
44	    const html = await this.fetchComponentPage(componentSlug);
45	    const $ = cheerio.load(html);
46	    
47	    // ReactBits stores code in script tags with specific IDs
48	    // Look for code blocks in the page
49	    const codeBlocks: { [key: string]: string } = {};
50	    
51	    // Find all code elements
52	    $('pre code').each((index, element) => {
53	      const code = $(element).text().trim();
54	      const parent = $(element).parent();
55	      const prevText = parent.prev().text().toLowerCase();
56	      
57	      // Try to identify if this is CSS or JS/TS code
58	      if (prevText.includes('css') || code.includes('.css') || code.includes('style')) {
59	        codeBlocks.css = code;
60	      } else if (prevText.includes('tailwind') || code.includes('className=')) {
61	        codeBlocks.tailwind = code;
62	      } else if (code.includes('import React') || code.includes('export default')) {
63	        if (!codeBlocks.default) {
64	          codeBlocks.default = code;
65	        }
66	      }
67	    });
68	
69	    // If no code blocks found, try parsing from inline scripts
70	    $('script').each((index, element) => {
71	      const scriptContent = $(element).html() || '';
72	      if (scriptContent.includes('__COMPONENT_CODE__') || scriptContent.includes('componentCode')) {
73	        try {
74	          // Extract code from script variables
75	          const matches = scriptContent.match(/(?:const|let|var)\s+\w+\s*=\s*`([^`]+)`/g);
76	          if (matches) {
77	            matches.forEach(match => {
78	              const code = match.match(/`([^`]+)`/)?.[1] || '';
79	              if (code.includes('className=')) {
80	                codeBlocks.tailwind = code;
81	              } else if (code.includes('.css') || code.includes('style=')) {
82	                codeBlocks.css = code;
83	              }
84	            });
85	          }
86	        } catch (e) {
87	          // Ignore parsing errors
88	        }
89	      }
90	    });
91	
92	    // Fallback: Create a basic component structure
93	    if (Object.keys(codeBlocks).length === 0) {
94	      const componentName = componentSlug
95	        .split('-')
96	        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
97	        .join('');
98	      
99	      codeBlocks.default = `import React from 'react';
100	
101	const ${componentName} = () => {
102	  return (
103	    <div className="relative">
104	      {/* Implementation for ${componentName} */}
105	      {/* Visit https://reactbits.dev/components/${componentSlug} for full implementation */}
106	    </div>
107	  );
108	};
109	
110	export default ${componentName};`;
111	    }
112	
113	    // Determine which version to return
114	    const preferredStyle = style || 'default';
115	    const code = codeBlocks[preferredStyle] || codeBlocks.tailwind || codeBlocks.css || codeBlocks.default || '';
116	
117	    // Extract imports and dependencies
118	    const imports = this.extractImports(code);
119	    const dependencies = this.extractDependencies(code);
120	
121	    return {
122	      code,
123	      style: preferredStyle,
124	      imports,
125	      dependencies
126	    };
